import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router';

export default function RetakeClassPage() {
  const __routeParams = useParams() as Record<string, string | undefined>;
  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    const __url = `/api/remedial/${encodeURIComponent(String(__routeParams.id ?? __routeParams.id ?? '__MISSING__'))}`;
    if (__url.indexOf('__MISSING__') !== -1) { if (!cancelled) setLoading1(false); return () => { cancelled = true; }; }
    fetch(__url, { credentials: 'include' })
      .then((r) => r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status)))
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e) => { if (!cancelled) setError1((e as Error).message); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, []);

  const [loading4, setLoading4] = useState<boolean>(false);
  const createComplete4 = async () => {
    setLoading4(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="retake-class-ac-4"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    try {
      const r = await fetch(`/api/remedial/${encodeURIComponent(String(__routeParams.id ?? __routeParams.id ?? '__MISSING__'))}/complete`, { method: "POST", credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(__body) });
      if (!r.ok) throw new Error('HTTP ' + r.status);
      // success — TODO: refresh related list / show success toast
    } catch (e) {
      // TODO: show error toast
      console.error(e);
    } finally {
      setLoading4(false);
    }
  };

  return (
    <div className="min-h-screen bg-white" data-testid="retake-class-page">
      <header className="border-b border-gray-200 p-4">
        <Link to="/" className="text-sm text-gray-500" data-testid="retake-class-home-link">Home</Link>
        <h1 className="mt-2 text-2xl font-bold" data-testid="retake-class-heading">Retake class — chapter refresher video and Bangla note, three-question understanding check, 2-retake cap and re-exam unlock</h1>
      </header>
      <main className="space-y-4 p-4" data-testid="retake-class-main">
          <section className="rounded border border-gray-200 p-4" data-testid="retake-class-ac-1">
            <h2 className="mb-2 text-lg font-semibold">The chapter refresher video, Bangla note and verification set load for the assigned retake</h2>
            {loading1 && <p data-testid="retake-class-ac-1-loading">Loading...</p>}
            {error1 && <p data-testid="retake-class-ac-1-error" className="text-red-600">Unable to load</p>}
            {!loading1 && !error1 && (
              <pre className="overflow-auto text-xs" data-testid="retake-class-ac-1-detail">{JSON.stringify(data1, null, 2)}</pre>
            )}
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="retake-class-ac-2">
            <h2 className="mb-2 text-lg font-semibold">Hero states why the retake was assigned and how much of the cap is spent</h2>
            <p className="text-sm text-gray-600">Badge 'চলছে' (retake-status), heading 'ভগ্নাংশের তুলনা — আবার শিখি' (retake-heading), reason body (retake-desc), cap label 'অগ্রগতি' (retake-cap-label), value '১ / ২ রিটেক শেষ' (retake-cap-value), bar at 50% (retake-cap-bar) and note 'দুটির একটি শেষ হয়েছে — বাকিটা শেষ হলে রি-এক্সাম খুলবে।' (retake-cap-note)</p>
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="retake-class-ac-3">
            <h2 className="mb-2 text-lg font-semibold">Answer the three-question understanding check, one question at a time</h2>
            <p className="text-sm text-gray-600">Panel 'বোঝাপড়া যাচাই' (retake-check-label) shows count '১ / ৩' (retake-check-count), question '১। ৩/৪ এর সমান কোনটি?' (retake-check-q1) and stacked option pills (retake-check-option) where only the chosen pill has aria-pressed=true; note 'সবগুলো প্রশ্নের উত্তর দিতে হবে — নইলে সম্পন্ন করা যাবে না।' (retake-check-note) stays visible</p>
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="retake-class-ac-4">
            <h2 className="mb-2 text-lg font-semibold">Complete the retake once every check question is answered</h2>
            <input name="title" type="text" placeholder="title" data-testid="retake-class-ac-4-title" className="mb-2 block w-full rounded border border-gray-300 px-3 py-2" />
            <input name="content" type="text" placeholder="content" data-testid="retake-class-ac-4-content" className="mb-2 block w-full rounded border border-gray-300 px-3 py-2" />
            <button
              type="button"
              onClick={createComplete4}
              disabled={loading4}
              className="rounded bg-blue-600 px-4 py-2 text-white disabled:opacity-50"
              data-testid="retake-class-ac-4-action"
            >
              {loading4 ? 'Submitting...' : 'Create'}
            </button>
          </section>
          <section className="rounded border border-gray-200 p-4" data-testid="retake-class-ac-5">
            <h2 className="mb-2 text-lg font-semibold">The unlocked re-exam button routes to the exam list</h2>
            <p className="text-sm text-gray-600">'রি-এক্সাম' (retake-reexam) is inert (rt-off, aria-disabled=true) while the check is incomplete and becomes a live link to /exams after completion; 'হোমে ফিরে যান' (retake-skip) always routes to /</p>
          </section>
      </main>
    </div>
  );
}
